    @GameTest(template="empty",batch="literary_fan",timeoutTicks=250)
    public static void actualPlacedReachRepairBladeStrikeAndTwoReturnsExposeTheTooth(GameTestHelper h){var f=new Fixture(h);var place=LabyrinthPlace.ELK_FAN;var p=f.player("fan_reader",place);f.source(p,place);var at=f.base(place).offset(1,0,-16);f.in.setBlock(at,Blocks.COBBLESTONE.defaultBlockState(),3);var event=new BlockEvent.EntityPlaceEvent(net.neoforged.neoforge.common.util.BlockSnapshot.create(f.in.dimension(),f.in,at),Blocks.AIR.defaultBlockState(),p);NeoForge.EVENT_BUS.post(event);h.assertTrue(!event.isCanceled()&&f.own(p,place).getBoolean("BuiltReach"),"a genuine final placed block is recorded even with an empty hand");f.click(p,place,LiteraryRooms.FAN);f.at(p,place,0,5,-17);f.look(p,f.base(place).offset(0,0,-17));h.runAfterDelay(90,()->{h.assertTrue(f.own(p,place).getBoolean("Repaired")&&f.own(p,place).getBoolean("BladeStrike")&&f.own(p,place).getBoolean("ElkThroughFan"),"repair, the physical fan sightline and native blade strike all belong to visit one");f.arrive(p,place);f.at(p,place,0,0,-15);f.look(p,f.base(place).offset(0,0,-17));});h.runAfterDelay(110,()->{h.assertTrue(f.own(p,place).getBoolean("TapeSeen"),"the next actual visit exposes the taped shape");f.arrive(p,place);f.at(p,place,0,0,-15);});h.runAfterDelay(130,()->{h.assertTrue(f.own(p,place).getBoolean("Ready"),"a third visit reaches the peeled outline");f.read(p,place,LiteraryRooms.ending(place));h.assertTrue(p.getInventory().countItem(LiteraryRegistry.TOOTH.get())==1,"the owned final reading gives the tooth once");f.read(p,place,LiteraryRooms.ending(place));h.assertTrue(p.getInventory().countItem(LiteraryRegistry.TOOTH.get())==1,"rereading cannot replenish it");h.succeed();});}
