    @GameTest(template="empty",batch="literary_registry",timeoutTicks=100)
    public static void eligibleSourcesAndOneOptionalClosureLeaveTheWitnessReachable(GameTestHelper h){var data=new LabyrinthData();var player=UUID.randomUUID();h.assertTrue(WitnessAccount.Story.values().length==43&&WitnessAccount.REQUIRED==33,"the quota derives from all eligible authored stories");h.assertTrue(WitnessAccount.Story.of("old_cabin")==null,"the recurring witness cabin is guidance, not another source");int sources=0;for(var place:LabyrinthPlace.values())if(LiteraryRooms.isLiterary(place)&&place!=LabyrinthPlace.OLD_CABIN){h.assertTrue(WitnessAccount.Story.of(place.id())!=null&&LiteraryTexts.source(place).has(DataComponents.WRITTEN_BOOK_CONTENT),"every new eligible site has original discovery writing and its own resolution registration");sources++;}h.assertTrue(sources==23&&WitnessAccount.Story.values().length-1>=WitnessAccount.REQUIRED,"one optional closure leaves forty-two sources for thirty-three required resolutions");for(var story:WitnessAccount.Story.values())WitnessAccount.resolve(data,player,story,"resolved");h.assertTrue(WitnessAccount.count(data,player)==43&&WitnessAccount.ready(data,player),"different choices in one story cannot add a second source");h.succeed();}
    @GameTest(template="empty",batch="literary_copy",timeoutTicks=500)
    public static void anActualSleptHomeCreatesPrivateFrozenCopiesWithEmptyOriginalContainers(GameTestHelper h){var f=new Fixture(h);var p=f.player("copy_reader",LabyrinthPlace.HILL_NURSERY);var peer=f.player("copy_peer",LabyrinthPlace.HILL_NURSERY);var world=p.server.overworld();var home=new BlockPos(63500,80,63500);var bed=home.offset(2,0,-3);LiteraryRooms.box(world,home,-32,-1,-32,31,-1,31,Blocks.STONE_BRICKS);NovelRooms.room(world,home,-10,10,-10,10,0,6,Blocks.OAK_PLANKS,Blocks.BIRCH_PLANKS);NovelRooms.door(world,home.offset(0,0,10),Direction.SOUTH,Blocks.OAK_DOOR,false);NovelRooms.bed(world,bed,Blocks.WHITE_BED,Direction.NORTH);world.setBlock(home.offset(-5,0,-3),Blocks.CRAFTING_TABLE.defaultBlockState(),3);world.setBlock(home.offset(-4,0,-4),Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)world.getBlockEntity(home.offset(-4,0,-4))).setItem(0,new ItemStack(Items.DIAMOND,7));world.setBlock(home.offset(5,0,-5),Blocks.PISTON.defaultBlockState(),3);world.setBlock(home.offset(7,0,-5),Blocks.HOPPER.defaultBlockState(),3);world.setBlock(home.offset(6,-1,-5),Blocks.FARMLAND.defaultBlockState(),3);world.setBlock(home.offset(6,0,-5),Blocks.WHEAT.defaultBlockState(),3);
        h.runAfterDelay(10,()->{p.teleportTo(world,home.getX()+.5,home.getY(),home.getZ()+11.5,180,0);p.hasChangedDimension();var door=home.offset(0,0,10);NeoForge.EVENT_BUS.post(new PlayerInteractEvent.RightClickBlock(p,InteractionHand.MAIN_HAND,door,new BlockHitResult(door.getCenter(),Direction.SOUTH,door,false)));world.setDayTime(18000);p.moveTo(bed.getX()+.5,bed.getY(),bed.getZ()+1.5);p.startSleeping(bed);});
        h.runAfterDelay(100,()->{p.stopSleepInBed(true,true);var family=LiteraryCopies.base(p.server,p.getUUID(),LabyrinthPlace.FAMILY_COPY);var cabin=LiteraryCopies.base(p.server,p.getUUID(),LabyrinthPlace.OLD_CABIN);h.assertTrue(family!=null&&cabin!=null,"real native sleep captures and constructs both independent bounded snapshots");h.assertTrue(LiteraryCopies.base(p.server,peer.getUUID(),LabyrinthPlace.FAMILY_COPY)==null,"an unslept peer receives no borrowed home");h.assertTrue(LiteraryCopies.prepareEntry(p,LabyrinthPlace.FAMILY_COPY)==null,"the family waits two actual in-game weeks");var chest=(ChestBlockEntity)f.out.getBlockEntity(family.offset(-6,0,-35));h.assertTrue(chest!=null&&chest.isEmpty(),"the actual copied container is empty while the seven source diamonds remain in the native home");h.assertTrue(((ChestBlockEntity)world.getBlockEntity(home.offset(-4,0,-4))).getItem(0).getCount()==7,"capture never takes source property");h.assertTrue(f.out.getBlockState(family.offset(3,0,-36)).is(LiteraryRegistry.FROZEN.get()),"the actual captured piston uses its inactive original mesh");h.assertTrue(f.out.getBlockState(family.offset(5,0,-36)).is(LiteraryRegistry.FROZEN.get())&&LiteraryFrozenBlock.original(f.out,family.offset(5,0,-36)).is(Blocks.HOPPER),"the captured hopper retains its native state without a ticking inventory or overwritten display data");world.setDayTime(14*24000L+18000);});
        h.runAfterDelay(115,()->{var family=LiteraryCopies.base(p.server,p.getUUID(),LabyrinthPlace.FAMILY_COPY);h.assertTrue(LiteraryCopies.prepareEntry(p,LabyrinthPlace.FAMILY_COPY)!=null,"maturity opens this reader's exact private entry");p.teleportTo(f.out,family.getX()+.5,family.getY(),family.getZ()-3,180,0);p.hasChangedDimension();LiteraryVignettes.onArrive(p,LabyrinthPlace.FAMILY_COPY);var chestAt=family.offset(-6,0,-35);p.moveTo(chestAt.getX()+.5,chestAt.getY(),chestAt.getZ()+2.5);var locked=new PlayerInteractEvent.RightClickBlock(p,InteractionHand.MAIN_HAND,chestAt,new BlockHitResult(chestAt.getCenter(),Direction.SOUTH,chestAt,false));NeoForge.EVENT_BUS.post(locked);h.assertTrue(locked.isCanceled(),"the empty copied chest is natively locked instead of accepting the visitor's property");f.source(p,LabyrinthPlace.FAMILY_COPY);var original=f.own(p,LabyrinthPlace.FAMILY_COPY).getCompound("Original_Source").copy();var copies=LiteraryCopies.get(p.server);p.server.overworld().getDataStorage().set("the_oldest_house_literary_copies",LiteraryCopies.load(copies.save(new CompoundTag(),p.registryAccess()),p.registryAccess()));h.assertTrue(family.equals(LiteraryCopies.base(p.server,p.getUUID(),LabyrinthPlace.FAMILY_COPY)),"native SavedData reload retains the private address and completed build cursor");f.source(p,LabyrinthPlace.FAMILY_COPY);h.assertTrue(original.equals(f.own(p,LabyrinthPlace.FAMILY_COPY).getCompound("Original_Source")),"copy readers keep the same finite paper after reload");try{ArchitectureTests.export(f.out,family,LabyrinthPlace.FAMILY_COPY);ArchitectureTests.export(f.out,LiteraryCopies.base(p.server,p.getUUID(),LabyrinthPlace.OLD_CABIN),LabyrinthPlace.OLD_CABIN);}catch(Exception e){throw new IllegalStateException(e);}h.succeed();});}
